[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>WellStream Platform — Integrated Energy Data Management</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&display=swap" rel="stylesheet">
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
    :root {
      --navy: #0D1B2A;
      --navy-dark: #091525;
      --charcoal: #1B2838;
      --charcoal-light: #243447;
      --teal: #00B4D8;
      --teal-dark: #0096B7;
      --blue: #0077B6;
      --green: #6CC24A;
      --gray: #3C424B;
      --gray-light: #5A6270;
      --white: #FFFFFF;
      --white-90: rgba(255,255,255,0.9);
      --white-70: rgba(255,255,255,0.7);
      --white-50: rgba(255,255,255,0.5);
      --white-20: rgba(255,255,255,0.2);
      --white-10: rgba(255,255,255,0.1);
    }
    html { scroll-behavior: smooth; }
    body {
      font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
      background: var(--navy);
      color: var(--white);
      line-height: 1.6;
      overflow-x: hidden;
    }
    a { color: inherit; text-decoration: none; }
    img { max-width: 100%; display: block; }

    /* Navigation */
    .nav {
      position: fixed;
      top: 0;
      left: 0;
      right: 0;
      z-index: 1000;
      background: rgba(13, 27, 42, 0.95);
      backdrop-filter: blur(12px);
      border-bottom: 1px solid var(--white-10);
    }
    .nav-container {
      max-width: 1280px;
      margin: 0 auto;
      padding: 0 24px;
      height: 72px;
      display: flex;
      align-items: center;
      justify-content: space-between;
    }
    .nav-logo {
      font-size: 24px;
      font-weight: 800;
      color: var(--white);
      display: flex;
      align-items: center;
      gap: 8px;
    }
    .nav-logo-icon {
      width: 36px;
      height: 36px;
      background: linear-gradient(135deg, var(--teal), var(--blue));
      border-radius: 8px;
      display: flex;
      align-items: center;
      justify-content: center;
    }
    .nav-logo-icon svg { width: 20px; height: 20px; }
    .nav-menu {
      display: flex;
      align-items: center;
      gap: 32px;
    }
    .nav-dropdown {
      position: relative;
    }
    .nav-dropdown-trigger {
      display: flex;
      align-items: center;
      gap: 4px;
      padding: 8px 0;
      font-size: 15px;
      font-weight: 500;
      color: var(--white-90);
      cursor: pointer;
      transition: color 0.2s;
    }
    .nav-dropdown-trigger:hover { color: var(--teal); }
    .nav-dropdown-trigger svg { width: 12px; height: 12px; transition: transform 0.2s; }
    .nav-dropdown:hover .nav-dropdown-trigger svg { transform: rotate(180deg); }
    .nav-dropdown-menu {
      position: absolute;
      top: 100%;
      left: -16px;
      min-width: 200px;
      background: var(--charcoal);
      border: 1px solid var(--white-10);
      border-radius: 12px;
      padding: 8px;
      opacity: 0;
      visibility: hidden;
      transform: translateY(8px);
      transition: all 0.2s;
    }
    .nav-dropdown:hover .nav-dropdown-menu {
      opacity: 1;
      visibility: visible;
      transform: translateY(0);
    }
    .nav-dropdown-item {
      display: block;
      padding: 10px 16px;
      font-size: 14px;
      font-weight: 500;
      color: var(--white-90);
      border-radius: 8px;
      transition: all 0.15s;
    }
    .nav-dropdown-item:hover {
      background: var(--white-10);
      color: var(--teal);
    }
    .nav-links {
      display: flex;
      gap: 24px;
    }
    .nav-link {
      font-size: 15px;
      font-weight: 500;
      color: var(--white-70);
      transition: color 0.2s;
    }
    .nav-link:hover { color: var(--white); }
    .btn {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 8px;
      padding: 12px 24px;
      font-size: 15px;
      font-weight: 600;
      border-radius: 8px;
      border: none;
      cursor: pointer;
      transition: all 0.2s;
    }
    .btn-primary {
      background: linear-gradient(135deg, var(--teal), var(--blue));
      color: var(--white);
    }
    .btn-primary:hover {
      transform: translateY(-2px);
      box-shadow: 0 8px 24px rgba(0, 180, 216, 0.3);
    }
    .btn-secondary {
      background: transparent;
      color: var(--white);
      border: 1px solid var(--white-30);
    }
    .btn-secondary:hover {
      border-color: var(--teal);
      color: var(--teal);
    }
    .mobile-menu-btn {
      display: none;
      background: none;
      border: none;
      cursor: pointer;
      padding: 8px;
    }
    .mobile-menu-btn svg { width: 24px; height: 24px; color: var(--white); }

    /* Hero */
    .hero {
      min-height: 100vh;
      display: flex;
      align-items: center;
      padding: 120px 24px 80px;
      position: relative;
      overflow: hidden;
    }
    .hero::before {
      content: '';
      position: absolute;
      top: 0;
      left: 0;
      right: 0;
      bottom: 0;
      background:
        radial-gradient(ellipse 80% 50% at 50% -20%, rgba(0, 180, 216, 0.15), transparent),
        radial-gradient(ellipse 60% 40% at 80% 60%, rgba(0, 119, 182, 0.1), transparent);
      pointer-events: none;
    }
    .hero-grid {
      max-width: 1280px;
      margin: 0 auto;
      width: 100%;
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 80px;
      align-items: center;
    }
    .hero-content { position: relative; z-index: 1; }
    .hero-label {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      padding: 8px 16px;
      background: var(--white-10);
      border-radius: 100px;
      font-size: 13px;
      font-weight: 600;
      color: var(--teal);
      text-transform: uppercase;
      letter-spacing: 0.05em;
      margin-bottom: 24px;
    }
    .hero-title {
      font-size: clamp(36px, 5vw, 56px);
      font-weight: 800;
      line-height: 1.1;
      margin-bottom: 24px;
      background: linear-gradient(135deg, var(--white) 0%, var(--white-90) 100%);
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
    }
    .hero-subtitle {
      font-size: 18px;
      color: var(--white-70);
      max-width: 520px;
      margin-bottom: 40px;
      line-height: 1.7;
    }
    .hero-ctas {
      display: flex;
      gap: 16px;
      flex-wrap: wrap;
    }
    .hero-visual {
      position: relative;
    }
    .hero-diagram {
      background: linear-gradient(135deg, var(--charcoal), var(--navy-dark));
      border: 1px solid var(--white-10);
      border-radius: 24px;
      padding: 40px;
      position: relative;
    }
    .hero-diagram::before {
      content: '';
      position: absolute;
      inset: -1px;
      border-radius: 24px;
      background: linear-gradient(135deg, var(--teal-20), transparent, var(--blue-20));
      z-index: -1;
    }
    .ecosystem-title {
      font-size: 14px;
      font-weight: 600;
      color: var(--teal);
      text-transform: uppercase;
      letter-spacing: 0.1em;
      margin-bottom: 24px;
      text-align: center;
    }
    .ecosystem-pillars {
      display: flex;
      flex-direction: column;
      gap: 16px;
    }
    .ecosystem-pillar {
      background: var(--white-05);
      border: 1px solid var(--white-10);
      border-radius: 16px;
      padding: 24px;
      display: flex;
      align-items: flex-start;
      gap: 20px;
      transition: all 0.3s;
    }
    .ecosystem-pillar:hover {
      border-color: var(--teal);
      transform: translateX(4px);
    }
    .pillar-icon {
      width: 48px;
      height: 48px;
      background: linear-gradient(135deg, var(--teal), var(--blue));
      border-radius: 12px;
      display: flex;
      align-items: center;
      justify-content: center;
      flex-shrink: 0;
    }
    .pillar-icon svg { width: 24px; height: 24px; color: var(--white); }
    .pillar-content h3 {
      font-size: 16px;
      font-weight: 700;
      margin-bottom: 6px;
    }
    .pillar-content p {
      font-size: 14px;
      color: var(--white-60);
      line-height: 1.5;
    }
    .ecosystem-connections {
      display: flex;
      justify-content: center;
      padding: 16px 0;
      position: relative;
    }
    .ecosystem-connections::before {
      content: '';
      position: absolute;
      top: 50%;
      left: 50%;
      transform: translate(-50%, -50%);
      width: 120px;
      height: 120px;
      background: radial-gradient(circle, rgba(0,180,216,0.2) 0%, transparent 70%);
      border-radius: 50%;
    }
    .connection-icon {
      width: 64px;
      height: 64px;
      background: var(--charcoal);
      border: 2px solid var(--teal);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      position: relative;
      z-index: 1;
    }
    .connection-icon svg { width: 28px; height: 28px; color: var(--teal); }

    /* Featured Banner */
    .featured-banner {
      background: linear-gradient(135deg, var(--charcoal-light), var(--charcoal));
      border-top: 1px solid var(--white-10);
      border-bottom: 1px solid var(--white-10);
      padding: 60px 24px;
    }
    .featured-container {
      max-width: 1280px;
      margin: 0 auto;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 40px;
    }
    .featured-badge {
      display: flex;
      align-items: center;
      gap: 12px;
    }
    .featured-badge-icon {
      width: 56px;
      height: 56px;
      background: linear-gradient(135deg, var(--green), #4a9a2a);
      border-radius: 14px;
      display: flex;
      align-items: center;
      justify-content: center;
    }
    .featured-badge-icon svg { width: 28px; height: 28px; color: var(--white); }
    .featured-info h3 {
      font-size: 20px;
      font-weight: 700;
      margin-bottom: 4px;
    }
    .featured-info span {
      font-size: 14px;
      color: var(--green);
      font-weight: 600;
    }

    /* Use Cases */
    .use-cases {
      padding: 120px 24px;
      background: var(--navy-dark);
    }
    .section-container {
      max-width: 1280px;
      margin: 0 auto;
    }
    .section-header {
      text-align: center;
      max-width: 720px;
      margin: 0 auto 64px;
    }
    .section-label {
      font-size: 13px;
      font-weight: 600;
      color: var(--teal);
      text-transform: uppercase;
      letter-spacing: 0.1em;
      margin-bottom: 16px;
    }
    .section-title {
      font-size: clamp(32px, 4vw, 48px);
      font-weight: 800;
      margin-bottom: 20px;
    }
    .section-desc {
      font-size: 18px;
      color: var(--white-70);
      line-height: 1.7;
    }
    .use-cases-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 24px;
      margin-bottom: 48px;
    }
    .use-case-card {
      background: var(--charcoal);
      border: 1px solid var(--white-10);
      border-radius: 20px;
      padding: 32px;
      transition: all 0.3s;
      cursor: pointer;
    }
    .use-case-card:hover {
      border-color: var(--teal);
      transform: translateY(-4px);
      box-shadow: 0 16px 48px rgba(0,0,0,0.3);
    }
    .use-case-icon {
      width: 48px;
      height: 48px;
      background: var(--white-10);
      border-radius: 12px;
      display: flex;
      align-items: center;
      justify-content: center;
      margin-bottom: 20px;
    }
    .use-case-icon svg { width: 24px; height: 24px; color: var(--teal); }
    .use-case-card h3 {
      font-size: 18px;
      font-weight: 700;
      margin-bottom: 12px;
    }
    .use-case-card p {
      font-size: 15px;
      color: var(--white-60);
      line-height: 1.6;
    }
    .section-cta {
      text-align: center;
    }

    /* Industry Tabs */
    .industry-section {
      padding: 120px 24px;
      background: var(--navy);
    }
    .industry-tabs {
      display: flex;
      justify-content: center;
      gap: 8px;
      margin-bottom: 48px;
      flex-wrap: wrap;
    }
    .industry-tab {
      padding: 12px 24px;
      font-size: 15px;
      font-weight: 600;
      color: var(--white-60);
      background: transparent;
      border: 1px solid var(--white-10);
      border-radius: 100px;
      cursor: pointer;
      transition: all 0.2s;
    }
    .industry-tab:hover {
      border-color: var(--white-30);
      color: var(--white);
    }
    .industry-tab.active {
      background: linear-gradient(135deg, var(--teal), var(--blue));
      color: var(--white);
      border-color: transparent;
    }
    .industry-content {
      display: none;
      max-width: 900px;
      margin: 0 auto;
    }
    .industry-content.active {
      display: block;
    }
    .industry-panel {
      background: var(--charcoal);
      border: 1px solid var(--white-10);
      border-radius: 24px;
      padding: 48px;
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 48px;
      align-items: center;
    }
    .industry-panel h3 {
      font-size: 28px;
      font-weight: 800;
      margin-bottom: 16px;
    }
    .industry-panel p {
      font-size: 16px;
      color: var(--white-70);
      line-height: 1.7;
      margin-bottom: 24px;
    }
    .industry-panel ul {
      list-style: none;
    }
    .industry-panel li {
      padding: 12px 0;
      font-size: 15px;
      color: var(--white-80);
      display: flex;
      align-items: center;
      gap: 12px;
    }
    .industry-panel li::before {
      content: '';
      width: 8px;
      height: 8px;
      background: var(--teal);
      border-radius: 50%;
    }
    .industry-visual {
      background: var(--white-05);
      border-radius: 16px;
      padding: 32px;
      display: flex;
      align-items: center;
      justify-content: center;
      min-height: 280px;
    }
    .industry-graphic {
      width: 100%;
      max-width: 320px;
    }

    /* Company Culture */
    .culture-section {
      padding: 120px 24px;
      background: linear-gradient(180deg, var(--navy-dark) 0%, var(--navy) 100%);
    }
    .culture-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 80px;
      align-items: center;
    }
    .culture-stats {
      display: grid;
      grid-template-columns: repeat(2, 1fr);
      gap: 32px;
      margin-top: 40px;
    }
    .culture-stat {
      background: var(--charcoal);
      border: 1px solid var(--white-10);
      border-radius: 16px;
      padding: 24px;
    }
    .culture-stat-value {
      font-size: 40px;
      font-weight: 800;
      color: var(--teal);
      margin-bottom: 4px;
    }
    .culture-stat-label {
      font-size: 14px;
      color: var(--white-60);
    }
    .culture-image {
      position: relative;
    }
    .culture-image-main {
      background: linear-gradient(135deg, var(--charcoal-light), var(--charcoal));
      border: 1px solid var(--white-10);
      border-radius: 24px;
      height: 400px;
      display: flex;
      align-items: center;
      justify-content: center;
      position: relative;
      overflow: hidden;
    }
    .culture-image-main::before {
      content: '';
      position: absolute;
      inset: 0;
      background: radial-gradient(circle at 30% 40%, rgba(0,180,216,0.15), transparent 60%);
    }
    .culture-image-icon {
      width: 120px;
      height: 120px;
      background: linear-gradient(135deg, var(--teal), var(--blue));
      border-radius: 32px;
      display: flex;
      align-items: center;
      justify-content: center;
      position: relative;
      z-index: 1;
    }
    .culture-image-icon svg { width: 56px; height: 56px; color: var(--white); }

    /* Renewables CTA */
    .renewables-section {
      padding: 120px 24px;
      background: var(--navy);
    }
    .renewables-card {
      background: linear-gradient(135deg, var(--charcoal-light), var(--charcoal));
      border: 1px solid var(--white-10);
      border-radius: 32px;
      padding: 80px;
      display: grid;
      grid-template-columns: 1fr auto;
      gap: 64px;
      align-items: center;
    }
    .renewables-card h2 {
      font-size: clamp(28px, 4vw, 40px);
      font-weight: 800;
      margin-bottom: 16px;
    }
    .renewables-card p {
      font-size: 18px;
      color: var(--white-70);
      max-width: 600px;
      line-height: 1.7;
    }

    /* Footer */
    .footer {
      background: var(--navy-dark);
      border-top: 1px solid var(--white-10);
      padding: 80px 24px 40px;
    }
    .footer-grid {
      max-width: 1280px;
      margin: 0 auto;
      display: grid;
      grid-template-columns: 2fr repeat(3, 1fr);
      gap: 64px;
      padding-bottom: 64px;
      border-bottom: 1px solid var(--white-10);
    }
    .footer-brand p {
      font-size: 15px;
      color: var(--white-60);
      margin-top: 16px;
      max-width: 320px;
      line-height: 1.7;
    }
    .footer-column h4 {
      font-size: 13px;
      font-weight: 600;
      color: var(--teal);
      text-transform: uppercase;
      letter-spacing: 0.1em;
      margin-bottom: 20px;
    }
    .footer-column ul {
      list-style: none;
    }
    .footer-column li {
      margin-bottom: 12px;
    }
    .footer-column a {
      font-size: 15px;
      color: var(--white-60);
      transition: color 0.2s;
    }
    .footer-column a:hover { color: var(--white); }
    .footer-bottom {
      max-width: 1280px;
      margin: 0 auto;
      padding-top: 40px;
      display: flex;
      justify-content: space-between;
      align-items: center;
    }
    .footer-bottom p {
      font-size: 14px;
      color: var(--white-50);
    }
    .footer-logins {
      display: flex;
      gap: 24px;
    }
    .footer-logins a {
      font-size: 14px;
      color: var(--white-50);
      transition: color 0.2s;
    }
    .footer-logins a:hover { color: var(--teal); }

    /* Cookie Banner */
    .cookie-banner {
      position: fixed;
      bottom: 24px;
      left: 24px;
      right: 24px;
      max-width: 480px;
      background: var(--charcoal);
      border: 1px solid var(--white-10);
      border-radius: 16px;
      padding: 24px;
      z-index: 999;
      display: none;
      box-shadow: 0 24px 64px rgba(0,0,0,0.4);
    }
    .cookie-banner.show { display: block; }
    .cookie-banner h4 {
      font-size: 16px;
      font-weight: 700;
      margin-bottom: 8px;
    }
    .cookie-banner p {
      font-size: 14px;
      color: var(--white-70);
      margin-bottom: 20px;
      line-height: 1.6;
    }
    .cookie-actions {
      display: flex;
      gap: 12px;
    }
    .cookie-actions .btn {
      flex: 1;
      padding: 12px 16px;
      font-size: 14px;
    }

    /* Mobile Styles */
    @media (max-width: 1024px) {
      .hero-grid { grid-template-columns: 1fr; gap: 48px; }
      .hero-visual { order: -1; }
      .use-cases-grid { grid-template-columns: repeat(2, 1fr); }
      .industry-panel { grid-template-columns: 1fr; }
      .culture-grid { grid-template-columns: 1fr; gap: 48px; }
      .renewables-card { grid-template-columns: 1fr; padding: 48px; }
      .footer-grid { grid-template-columns: repeat(2, 1fr); }
    }
    @media (max-width: 768px) {
      .nav-menu { display: none; }
      .mobile-menu-btn { display: block; }
      .nav-links { display: none; }
      .use-cases-grid { grid-template-columns: 1fr; }
      .featured-container { flex-direction: column; text-align: center; }
      .footer-grid { grid-template-columns: 1fr; gap: 40px; }
      .footer-bottom { flex-direction: column; gap: 16px; }
      .ecosystem-pillars { gap: 12px; }
      .ecosystem-pillar { padding: 16px; }
      .pillar-icon { width: 40px; height: 40px; }
    }

    /* Animations */
    @keyframes fadeInUp {
      from { opacity: 0; transform: translateY(20px); }
      to { opacity: 1; transform: translateY(0); }
    }
    .animate-in {
      animation: fadeInUp 0.6s ease-out forwards;
    }
  </style>
</head>
<body>
  <!-- Navigation -->
  <nav class="nav">
    <div class="nav-container">
      <a href="index.html" class="nav-logo">
        <div class="nav-logo-icon">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
            <path d="M12 2L2 7l10 5 10-5-10-5z"/>
            <path d="M2 17l10 5 10-5"/>
            <path d="M2 12l10 5 10-5"/>
          </svg>
        </div>
        WellStream
      </a>
      <div class="nav-menu">
        <div class="nav-dropdown">
          <span class="nav-dropdown-trigger">
            Platform
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M6 9l6 6 6-6"/></svg>
          </span>
          <div class="nav-dropdown-menu">
            <a href="platform-overview.html" class="nav-dropdown-item">Platform Overview</a>
            <a href="security.html" class="nav-dropdown-item">Security</a>
            <a href="integration.html" class="nav-dropdown-item">Integration</a>
