    @media (max-width: 768px) {
      .nav-menu { display: none; }
      .mobile-menu-btn { display: block; }
      .nav-links { display: none; }
      .benefits-grid { grid-template-columns: repeat(2, 1fr); }
      .stats-grid { grid-template-columns: 1fr; gap: 48px; }
      .stat-circle { width: 150px; height: 150px; }
      .timeline-item { grid-template-columns: 1fr; gap: 16px; }
      .timeline-duration { text-align: left; }
      .footer-grid { grid-template-columns: 1fr; gap: 40px; }
      .footer-bottom { flex-direction: column; gap: 16px; }
    }
    @media (max-width: 480px) {
      .benefits-grid { grid-template-columns: 1fr; }
      .accordion-header { padding: 20px; }
      .lifecycle-stage { padding: 24px 16px; }
    }
  </style>
